    line = line.strip()
    if not line: continue
    try:
        d = json.loads(line)
        t = d.get('type', '')
        if t == 'assistant':
            msg = d.get('message', {})
            for c in msg.get('content', []):
                if c.get('type') == 'tool_use':
                    name = c.get('name', '')
                    inp = c.get('input', {})
                    cmd = inp.get('command', '')[:300] if isinstance(inp.get('command'), str) else ''
                    if 'ssh' in name.lower():
                        print(f'L{i+1}: {name}: {cmd}')
                elif c.get('type') == 'text':
                    text = c.get('text', '')[:200]
                    if text:
                        print(f'L{i+1}: TEXT: {text}')
        elif t == 'user':
            msg = d.get('message', {})
            for c in msg.get('content', []):
                if isinstance(c, dict) and c.get('type') == 'tool_result':
                    content = str(c.get('content', ''))
                    if len(content) > 500:
                        has_gar = 'gar_curves' in content
                        has_ppl = 'ppl_per_conv' in content
                        has_beta = 'beta' in content
                        print(f'L{i+1}: RESULT len={len(content)} gar={has_gar} ppl={has_ppl} beta={has_beta}')
    except:
        pass
